 * Author: @omer-fils-elenga (https://tailwindflex.com/@omer-fils-elenga)
 * Source: https://tailwindflex.com/@omer-fils-elenga/about-video
 * Attribution: Créé par @omer-fils-elenga sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function AboutVideo() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!-- js for video alpinejs -->



    <section id="about" class="relative isolate overflow-hidden py-24 sm:py-32 bg-gradient-to-b from-gray-50 to-white">
    <!-- Background elements -->
    <div class="absolute inset-0 -z-10">
        <div class="absolute inset-y-0 right-1/2 -z-10 w-[200%] skew-x-[-30deg] bg-white shadow-xl shadow-gray-200/50 sm:right-1/2 sm:skew-x-0 md:right-2/3"></div>
        <div class="absolute left-0 top-0 -z-20 h-1/3 w-full rounded-b-full bg-gradient-to-r from-primary-light/10 to-primary/10 blur-3xl"></div>
        <div class="absolute right-0 bottom-0 -z-20 h-1/3 w-full rounded-t-full bg-gradient-to-l from-primary-light/10 to-primary/10 blur-3xl"></div>
    </div>

    <div class="mx-auto max-w-7xl px-6 lg:px-8">
        <div class="text-center mb-16">
            <h2 class="text-4xl md:text-5xl font-bold text-gray-900 mb-4 animate-fade-in [animation-fill-mode:both] [animation-delay:200ms]">
                Qu'est-ce que <span class="text-transparent bg-clip-text bg-gradient-to-r from-primary to-primary-light">Kela+</span> ?
            </h2>
            <div class="w-20 h-1.5 bg-gradient-to-r from-primary to-primary-light mx-auto mb-6 rounded-full animate-grow [animation-fill-mode:both] [animation-delay:400ms]"></div>
            <p class="text-lg md:text-xl text-gray-600 max-w-3xl mx-auto leading-relaxed animate-fade-in [animation-fill-mode:both] [animation-delay:600ms]">
                Découvrez Kela+ à travers cette vidéo de présentation qui vous montrera son fonctionnement innovant et comment il peut transformer votre expérience.
            </p>
        </div>

        <!-- Enhanced 3D Video Component -->
        <div class="[&_[x-cloak]]:hidden" x-data="{ modalOpen: false }">
            <style>
                .video-thumbnail-container {
                    perspective: 1200px;
                    max-width: 900px;
                    margin: 0 auto;
                }
                .video-thumbnail-wrapper {
                    position: relative;
                    transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
                    transform-style: preserve-3d;
                }
                .video-thumbnail {
                    border-radius: 1.5rem;
                    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.15);
                    transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
                    backface-visibility: hidden;
                    width: 100%;
                    height: auto;
                    aspect-ratio: 16/9;
                    object-fit: cover;
                }
                .video-thumbnail-container:hover .video-thumbnail-wrapper {
                    transform: rotateY(10deg) rotateX(3deg) scale(1.02);
                }
                .video-thumbnail-container:hover .video-thumbnail {
                    box-shadow: 0 32px 64px -12px rgba(0, 0, 0, 0.2);
                }
                .play-button {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                    width: 80px;
                    height: 80px;
                    background: rgba(255, 255, 255, 0.9);
                    border-radius: 50%;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    transition: all 0.3s ease;
                    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
                    backdrop-filter: blur(4px);
                }
                .play-button svg {
                    width: 30px;
                    height: 30px;
                    margin-left: 4px;
                }
                .video-thumbnail-container:hover .play-button {
                    transform: translate(-50%, -50%) scale(1.1) translateZ(30px);
                    background: rgba(255, 255, 255, 1);
                }
                .video-thumbnail-container::before {
                    content: '';
                    position: absolute;
                    inset: -10px;
                    background: linear-gradient(45deg, #4f46e5, #7c3aed, #9333ea);
                    z-index: -1;
                    filter: blur(20px);
                    opacity: 0;
                    transition: opacity 0.3s ease;
                    border-radius: 1.5rem;
                }
                .video-thumbnail-container:hover::before {
                    opacity: 0.4;
                }

                @media (max-width: 768px) {
                    .video-thumbnail-container {
                        perspective: 800px;
                    }
                    .play-button {
                        width: 60px;
                        height: 60px;
                    }
                    .play-button svg {
                        width: 24px;
                        height: 24px;
                    }
                }
            </style>

            <!-- Video thumbnail with enhanced 3D effect -->
            <div class="video-thumbnail-container px-4 sm:px-0 animate-float [animation-fill-mode:both] [animation-delay:800ms]">
                <button 
                    class="video-thumbnail-wrapper w-full h-full focus:outline-none" 
                    @click="modalOpen = true" 
                    aria-controls="modal" 
                    aria-label="Regarder la vidéo de présentation"
                >
                  <img 
                        class="video-thumbnail bg-white"
                        src="https://images.unsplash.com/photo-1573148195900-7845dcb9b127?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w0NzEyNjZ8MHwxfHNlYXJjaHwxMXx8aXBob25lfGVufDB8MHx8fDE3NTIzMjc5Njd8MA&ixlib=rb-4.1.0&q=80&w=1080" 
                        alt="Présentation vidéo de Kela+" 

                    />
                    <div class="play-button">
                        <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M8 5V19L19 12L8 5Z" fill="#4F46E5"/>
                        </svg>
                    </div>
                </button>
            </div>

            <!-- Modal backdrop -->
            <div
                class="fixed inset-0 z-[99999] bg-black/80 backdrop-blur-sm transition-opacity"
                x-show="modalOpen"
                x-transition:enter="transition ease-out duration-200"
                x-transition:enter-start="opacity-0"
                x-transition:enter-end="opacity-100"
                x-transition:leave="transition ease-out duration-100"
                x-transition:leave-start="opacity-100"
                x-transition:leave-end="opacity-0" 
                aria-hidden="true"
                x-cloak
            ></div>

            <!-- Modal dialog -->
            <div
                id="modal"
                class="fixed inset-0 z-[99999] flex px-4 md:px-6 py-6"
                role="dialog"
                aria-modal="true"
                x-show="modalOpen"
                x-transition:enter="transition ease-out duration-300"
                x-transition:enter-start="opacity-0 scale-90"
                x-transition:enter-end="opacity-100 scale-100"
                x-transition:leave="transition ease-out duration-200"
                x-transition:leave-start="opacity-100 scale-100"
                x-transition:leave-end="opacity-0 scale-90"
                x-cloak
            >
                <div class="max-w-6xl mx-auto h-full flex items-center w-full">
                    <div class="w-full max-h-full rounded-2xl shadow-2xl aspect-video bg-black overflow-hidden relative" @click.outside="modalOpen = false" @keydown.escape.window="modalOpen = false">
                        <button 
                            @click="modalOpen = false" 
                            class="absolute -top-12 right-0 text-white hover:text-gray-300 transition-colors"
                            aria-label="Fermer la vidéo"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <line x1="18" y1="6" x2="6" y2="18"></line>
                                <line x1="6" y1="6" x2="18" y2="18"></line>
                            </svg>
                        </button>
                        <video 
                            x-init="$watch('modalOpen', value => value ? $el.play() : $el.pause())" 
                            width="1920" 
                            height="1080" 
                            loop 
                            controls
                            class="w-full h-full object-cover"
                        >
                            <source src="https://cruip-tutorials.vercel.app/modal-video/video.mp4" type="video/mp4" />
                            Votre navigateur ne supporte pas les vidéos.
                        </video>
                    </div>
                </div>
            </div>
        </div>
    </div>
    </section>


    <p class="text-center text-sm">Create by omer fils Elenga in congo Brazzaville</p>



<!-- style  -->



    <style>

        @keyframes fade-in {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        @keyframes grow {
            from { transform: scaleX(0); }
            to { transform: scaleX(1); }
        }

        @keyframes float {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
        }

        .animate-fade-in {
            animation: fade-in 0.6s ease-out forwards;
        }

        .animate-grow {
            animation: grow 0.6s ease-out forwards;
            transform-origin: center;
        }

        .animate-float {
            animation: float 6s ease-in-out infinite;
        }
    </style>


<!-- script tailwind conf -->
" }} />
  );
}
